[CmdletBinding()]
param([Parameter(Mandatory=$true)][string[]]$Path,[string]$ProjectRoot='.',[int]$MaxParallel=4,[string]$OutputPath='ES/Output/Benchmarks/resource-reader-cache-parallel-perf.json')
$ErrorActionPreference='Stop'; $root=(Resolve-Path $ProjectRoot).Path; $cached=Join-Path $root '.agents/skills/es-resource-reader/scripts/Invoke-ESResourceReaderCached.ps1'; $read=Join-Path $root '.agents/skills/es-task-read-snapshot/scripts/Invoke-ESProjectionCache.ps1'; $jobs=@()
foreach($p in $Path){$source=(Resolve-Path $p).Path; $relative=$source.Substring($root.Length).TrimStart('\','/').Replace('\','/'); $ext=[IO.Path]::GetExtension($source).ToLowerInvariant(); $parser='bytes.v1'; if($ext -eq '.json'){$parser='json.v1'}elseif($ext -eq '.pdf'){$parser='pdf.probe.v1'}elseif($ext -eq '.xlsx'){$parser='xlsx.probe.v1'}elseif($ext -eq '.unitypackage'){$parser='unitypackage.python-tar.v1'}elseif($ext -in @('.png','.jpg','.jpeg','.wav','.ogg','.mp3','.mp4','.mov','.gltf','.obj','.fbx','.ttf','.otf','.woff','.woff2')){$parser='media.probe.v1'}; $null=& $cached -Path $source -ProjectRoot $root | Out-String; $jobs+=,[pscustomobject]@{relative=$relative;parser=$parser} }
$worker={param($item,$rootPath,$readerPath) $sw=[Diagnostics.Stopwatch]::StartNew(); $r=& $readerPath -Mode Read -ProjectRoot $rootPath -SourcePath $item.relative -ParserId $item.parser -ParserVersion '1' -CacheRoot 'ES/Output/FileProjectionCache'|ConvertFrom-Json; $sw.Stop(); [pscustomobject]@{path=$item.relative;status=$r.status;elapsedMs=$sw.Elapsed.TotalMilliseconds}}
$pool=[RunspaceFactory]::CreateRunspacePool(1,[math]::Max(1,$MaxParallel));$pool.Open();$pending=@();$swAll=[Diagnostics.Stopwatch]::StartNew();foreach($item in $jobs){$ps=[PowerShell]::Create();$ps.RunspacePool=$pool;[void]$ps.AddScript($worker).AddArgument($item).AddArgument($root).AddArgument($read);$pending+=,[pscustomobject]@{ps=$ps;handle=$ps.BeginInvoke()}};$results=@();foreach($j in $pending){try{$results+=@($j.ps.EndInvoke($j.handle))}finally{$j.ps.Dispose()}};$swAll.Stop();$pool.Close();$pool.Dispose();$hits=@($results|Where-Object status -eq 'hit');$times=@($hits|ForEach-Object elapsedMs|Sort-Object);$out=[ordered]@{schemaVersion=1;benchmarkId='es-resource-reader.cache-parallel-perf.v1';fileCount=$jobs.Count;maxParallel=$MaxParallel;hitCount=$hits.Count;missCount=($jobs.Count-$hits.Count);hitRate=if($jobs.Count){[math]::Round($hits.Count/$jobs.Count,4)}else{0};elapsedMilliseconds=$swAll.ElapsedMilliseconds;p50Ms=if($times.Count){$times[[math]::Floor(($times.Count-1)*.5)]}else{0};p95Ms=if($times.Count){$times[[math]::Floor(($times.Count-1)*.95)]}else{0};items=@($results|Sort-Object path);nonClaims=@('cold parser latency','Unity runtime','release')};$dest=Join-Path $root $OutputPath;New-Item -ItemType Directory -Force -Path (Split-Path $dest)|Out-Null;$out|ConvertTo-Json -Depth 8|Set-Content -LiteralPath $dest -Encoding UTF8;$out|ConvertTo-Json -Depth 8
